{    
    // ⚠️ IMPORTANTE: Solo se puede enviar a teléfonos o a grupos, pero no a ambos al mismo tiempo.

    // Lista de números de teléfono separados por coma.
    // Deben estar en formato nacional o internacional con indicativo (ej. 57 para Colombia).
    "phones": "573201234567,311123456789",

    // Identificador de uno o más grupos registrados en Onurix (comentado si se usan "phones").
    // "groups": "1,5",

    // Sección HEADER de la plantilla de WhatsApp.
    // Aquí puedes enviar archivos como documentos, imágenes o texto, según lo definido en la plantilla.
    "header": {
        "1": {
            "type": "document", // Tipo de variable: "text", "image", "video", "document"
            "value": {
                "link": "https://ejemplo.com/documento.pdf", // URL pública del documento
                // "meta_media_id": "MEDIA_ID_OPTIONAL", // Opcional: ID del recurso multimedia cargado en Meta
                "filename": "nombre-del-archivo.pdf" // Nombre que verá el usuario al recibirlo
            }
        }
    },

    // Sección BODY de la plantilla.
    // Estas variables serán insertadas en el cuerpo del mensaje.
    "body": {
        "1": {
            "type": "text",
            "value": "Nombre del usuario"
        },
        "2": {
            "type": "text",
            "value": "Mensaje personalizado u otra información"
        }
    },

    // Sección BUTTON de la plantilla.
    // Aquí puedes configurar botones si la plantilla los admite.
    "button": {
        // "1": {
        //     "type": "text",
        //     "value": "Texto del botón"
        // }
    }
}

